"""Illumination balancing and multi-variant depth fusion for depth estimation."""

from __future__ import annotations

import math

import torch
import torch.nn.functional as F


DEFAULT_VARIANT_STRENGTHS = "0,50,100"
# Brightening a dark region is riskier than darkening a bright one, so lift is
# scaled down relative to suppression.
LIFT_RATIO = 0.55
MAX_VARIANTS = 9
MAX_RADIUS = 512
FUSION_METHODS = ("中值", "均值", "截尾均值")
LUMA_WEIGHTS = (0.2126, 0.7152, 0.0722)
LN2 = math.log(2.0)
_EPS = 1e-6


def _srgb_to_linear(rgb: torch.Tensor) -> torch.Tensor:
    rgb = rgb.clamp(0.0, 1.0)
    return torch.where(
        rgb <= 0.04045,
        rgb / 12.92,
        ((rgb + 0.055) / 1.055).pow(2.4),
    )


def _linear_to_srgb(linear: torch.Tensor) -> torch.Tensor:
    linear = linear.clamp_min(0.0)
    return torch.where(
        linear <= 0.0031308,
        linear * 12.92,
        1.055 * linear.pow(1.0 / 2.4) - 0.055,
    ).clamp(0.0, 1.0)


def _luminance(rgb: torch.Tensor) -> torch.Tensor:
    return (
        rgb[:, 0:1] * LUMA_WEIGHTS[0]
        + rgb[:, 1:2] * LUMA_WEIGHTS[1]
        + rgb[:, 2:3] * LUMA_WEIGHTS[2]
    )


def _box_filter(image: torch.Tensor, radius: int) -> torch.Tensor:
    """Box filter whose cost does not grow with radius, via a summed-area table."""
    if radius <= 0:
        return image
    size = 2 * radius + 1
    padded = F.pad(image, (radius, radius, radius, radius), mode="replicate")
    cumulative = padded.cumsum(dim=-1)
    cumulative = F.pad(cumulative, (1, 0))
    horizontal = (cumulative[..., size:] - cumulative[..., :-size]) / size
    cumulative = horizontal.cumsum(dim=-2)
    cumulative = F.pad(cumulative, (0, 0, 1, 0))
    return (cumulative[..., size:, :] - cumulative[..., :-size, :]) / size


def _guided_filter(
    guide: torch.Tensor,
    source: torch.Tensor,
    radius: int,
    eps: torch.Tensor,
) -> torch.Tensor:
    """Edge-aware refinement of a smooth source, guided by `guide`."""
    mean_guide = _box_filter(guide, radius)
    mean_source = _box_filter(source, radius)
    corr_guide = _box_filter(guide * guide, radius)
    corr_cross = _box_filter(guide * source, radius)
    var_guide = (corr_guide - mean_guide * mean_guide).clamp_min(0.0)
    cov_cross = corr_cross - mean_guide * mean_source
    a = cov_cross / (var_guide + eps)
    b = mean_source - a * mean_guide
    return _box_filter(a, radius) * guide + _box_filter(b, radius)


def _illumination_field(log_luma: torch.Tensor, radius: int) -> torch.Tensor:
    """Halo-resistant low-frequency illumination estimate.

    A plain low-pass across a hard dark/bright boundary ramps down into the dark
    side, so removing it paints a bright glow around dark objects. The estimate
    is therefore refined with an edge-aware filter that follows the image, which
    keeps the falloff on the correct side of the boundary. The first stage is a
    pyramid low-pass, so the field stays genuinely low frequency instead of
    degenerating into a per-pixel tone curve that amplifies noise.
    """
    radius = max(2, int(radius))
    step = max(2, radius // 4)
    small = F.avg_pool2d(log_luma, step)
    small = _box_filter(small, max(1, radius // step))
    coarse = F.interpolate(
        small, size=log_luma.shape[-2:], mode="bilinear", align_corners=False
    )
    guide = _box_filter(log_luma, max(1, radius // 8))
    variance = guide.var(dim=(2, 3), keepdim=True)
    eps = (variance * 0.5).clamp_min(1e-4)
    return _guided_filter(guide, coarse, max(2, radius // 2), eps)


def _soft_limit(value: torch.Tensor, limit: float) -> torch.Tensor:
    """Soft-clamp a log-domain correction to +/- limit while keeping local order."""
    if limit <= 0.0:
        return torch.zeros_like(value)
    return limit * torch.tanh(value / limit)


def _auto_radius(height: int, width: int) -> int:
    return int(min(MAX_RADIUS, max(8, round(min(height, width) / 12.0))))


def _parse_strengths(text) -> list[float]:
    raw = str(text).replace("，", ",").replace(";", ",").replace(chr(10), ",")
    values: list[float] = []
    for token in raw.split(","):
        token = token.strip()
        if not token:
            continue
        try:
            value = float(token)
        except ValueError as exc:
            raise ValueError(f"档位强度无法解析: {token!r}") from exc
        values.append(min(100.0, max(0.0, value)))
    if not values:
        values = [50.0]
    if len(values) > MAX_VARIANTS:
        raise ValueError(
            f"档位数量最多 {MAX_VARIANTS} 档，当前 {len(values)} 档"
        )
    return values


def _balance_batch(
    rgb: torch.Tensor,
    strength: float,
    shadow_detail: float,
    max_ev: float,
    radius: int,
) -> torch.Tensor:
    if strength <= 0.0 and shadow_detail <= 0.0:
        return rgb
    linear = _srgb_to_linear(rgb)
    luma = _luminance(linear).clamp_min(_EPS)
    log_luma = luma.log()
    limit = max(float(max_ev), 0.0) * LN2

    field = _illumination_field(log_luma, radius)
    mean_field = field.mean(dim=(2, 3), keepdim=True)
    deviation = field - mean_field
    # Lift is deliberately gentler than suppression: a dark region is at least
    # as likely to be a genuinely dark object as a shadow, and over-lifting it
    # turns into glow and blown highlights around dark subjects.
    gain = torch.where(
        deviation < 0.0,
        torch.full_like(deviation, 1.0),
        torch.full_like(deviation, LIFT_RATIO),
    )
    correction = _soft_limit(-(strength / 100.0) * gain * deviation, limit)
    balanced = log_luma + correction
    # Re-anchor so the global log-median brightness is preserved exactly. Depth
    # Pro's focal head reads whole-image statistics, so any global shift here
    # could bias the metric scale even when the gradient correction is right.
    anchor = (balanced.flatten(2).median(dim=2).values
              - log_luma.flatten(2).median(dim=2).values)
    balanced = balanced - anchor.unsqueeze(-1)

    if shadow_detail > 0.0:
        detail_radius = max(2, radius // 8)
        base = _box_filter(balanced, detail_radius)
        shadow_weight = ((0.35 - luma) / 0.35).clamp(0.0, 1.0).pow(1.5)
        boost = _soft_limit(
            (shadow_detail / 100.0) * 1.25 * shadow_weight * (balanced - base), limit
        )
        balanced = balanced + boost

    ratio = (balanced - log_luma).exp().clamp(0.0, 8.0)
    return _linear_to_srgb(linear * ratio)


class QQIlluminationBalance:
    """Flatten low-frequency illumination gradients and emit several strengths."""

    CATEGORY = "QQ/工具"
    FUNCTION = "balance"
    RETURN_TYPES = ("IMAGE", "INT")
    RETURN_NAMES = ("图像", "档位数")
    DESCRIPTION = (
        "在线性光空间用引导滤波估计低频照度，"
        "只压缩照度梯度而不动细节层，保留全局中位亮度，"
        "并对修正幅度做软限幅以避免光晕。"
        "按档位强度输出多档变体（档位 0 即原图），"
        "配合 QQ-深度融合 做中值融合。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "image": ("IMAGE",),
                "档位强度": (
                    "STRING",
                    {
                        "default": DEFAULT_VARIANT_STRENGTHS,
                        "multiline": False,
                        "tooltip": "逗号分隔的照度均衡强度，0-100；0 表示该档保留原图。建议至少 3 档。",
                    },
                ),
                "暗部细节": (
                    "FLOAT",
                    {"default": 0.0, "min": 0.0, "max": 100.0, "step": 1.0},
                ),
                "最大修正幅度": (
                    "FLOAT",
                    {"default": 1.0, "min": 0.0, "max": 4.0, "step": 0.1},
                ),
                "滤波半径": (
                    "INT",
                    {"default": 0, "min": 0, "max": MAX_RADIUS, "step": 8},
                ),
                "全局曝光归一": ("BOOLEAN", {"default": False}),
            }
        }

    @staticmethod
    def balance(
        image,
        档位强度=DEFAULT_VARIANT_STRENGTHS,
        暗部细节=0.0,
        最大修正幅度=1.0,
        滤波半径=0,
        全局曝光归一=False,
    ):
        if not isinstance(image, torch.Tensor) or image.ndim != 4:
            raise TypeError(
                "照度均衡需要 ComfyUI 的 [batch, height, width, channels] 图像张量"
            )
        channels = int(image.shape[-1])
        if channels < 3:
            raise ValueError("照度均衡需要至少包含 RGB 三个通道")

        strengths = _parse_strengths(档位强度)
        height, width = int(image.shape[1]), int(image.shape[2])
        radius = int(滤波半径)
        if radius <= 0:
            radius = _auto_radius(height, width)
        radius = int(min(MAX_RADIUS, max(1, radius)))

        source = image[..., :3].movedim(-1, 1).to(dtype=torch.float32)
        outputs: list[torch.Tensor] = []
        global_gains = None
        if bool(全局曝光归一):
            medians = _luminance(_srgb_to_linear(source)).flatten(2).median(dim=2).values
            medians = medians.clamp_min(_EPS)
            target = medians.median()
            global_gains = (target / medians).view(-1, 1, 1, 1)

        for index in range(source.shape[0]):
            base = source[index : index + 1]
            gain = None if global_gains is None else global_gains[index : index + 1]
            for strength in strengths:
                variant = _balance_batch(
                    base,
                    strength,
                    float(暗部细节),
                    float(最大修正幅度),
                    radius,
                )
                if gain is not None:
                    variant = (variant * gain).clamp(0.0, 1.0)
                outputs.append(variant)

        stacked = torch.cat(outputs, dim=0).movedim(1, -1)
        if channels > 3:
            alpha = image[..., 3:].to(dtype=torch.float32)
            alpha = alpha.repeat_interleave(len(strengths), dim=0)
            stacked = torch.cat((stacked, alpha), dim=-1)
        return (stacked.to(dtype=image.dtype), len(strengths))


def _reduce_channels(depth: torch.Tensor) -> torch.Tensor:
    if depth.shape[1] == 1:
        return depth
    return depth.mean(dim=1, keepdim=True)


def _fuse_variants(values: torch.Tensor, method: str) -> torch.Tensor:
    if values.shape[1] == 1:
        return values[:, 0]
    if method == "均值":
        return values.mean(dim=1)
    if method == "截尾均值" and values.shape[1] >= 3:
        ordered = values.sort(dim=1).values
        return ordered[:, 1:-1].mean(dim=1)
    return values.median(dim=1).values


class QQDepthFusion:
    """Median-fuse several depth maps of the same image and report agreement."""

    CATEGORY = "QQ/工具"
    FUNCTION = "fuse"
    RETURN_TYPES = ("IMAGE", "IMAGE")
    RETURN_NAMES = ("融合深度", "一致性")
    DESCRIPTION = (
        "把 QQ-照度均衡 输出的多档变体对应的多路深度按图分组融合，"
        "默认做尺度归一后的中值融合，并输出一张一致性图："
        "越白表示各档位结果越一致，越黑表示该图对照度处理越敏感，建议人工复核。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "depth": ("IMAGE",),
                "每图档位数": (
                    "INT",
                    {
                        "default": len(_parse_strengths(DEFAULT_VARIANT_STRENGTHS)),
                        "min": 1,
                        "max": MAX_VARIANTS,
                        "tooltip": "接 QQ-照度均衡 的档位数输出，或手动填写每张图对应的深度图数量。",
                    },
                ),
                "融合方式": (list(FUSION_METHODS), {"default": "中值"}),
                "尺度归一": ("BOOLEAN", {"default": True}),
                "一致性增益": (
                    "FLOAT",
                    {"default": 3.0, "min": 0.0, "max": 10.0, "step": 0.5},
                ),
            }
        }

    @staticmethod
    def fuse(depth, 每图档位数=3, 融合方式="中值", 尺度归一=True, 一致性增益=3.0):
        if not isinstance(depth, torch.Tensor) or depth.ndim != 4:
            raise TypeError(
                "深度融合需要 ComfyUI 的 [batch, height, width, channels] 深度张量"
            )
        count = int(每图档位数)
        if count < 1:
            raise ValueError("每图档位数至少为 1")
        total = int(depth.shape[0])
        if total % count != 0:
            raise ValueError(
                f"深度图数量 {total} 无法被每图档位数 {count} 整除，"
                "请确认 QQ-照度均衡 的档位数与深度图数量一致"
            )

        images = total // count
        height, width = int(depth.shape[1]), int(depth.shape[2])
        values = _reduce_channels(depth.movedim(-1, 1).to(dtype=torch.float32))
        values = values.view(images, count, 1, height, width).squeeze(2)

        if bool(尺度归一):
            scales = values.flatten(2).median(dim=2).values.clamp_min(_EPS)
            normalised = values / scales.view(images, count, 1, 1)
            fused = _fuse_variants(normalised, 融合方式)
            anchor = scales.median(dim=1).values.view(images, 1, 1)
            fused = fused * anchor
        else:
            normalised = values
            fused = _fuse_variants(values, 融合方式)

        # Median absolute deviation collapses to zero whenever two of three
        # variants agree, so the full range is used instead: it stays sensitive
        # to a single dissenting variant, which is what a warning signal needs.
        middle = normalised.median(dim=1).values
        spread = normalised.max(dim=1).values - normalised.min(dim=1).values
        relative = spread / middle.abs().clamp_min(_EPS)
        consistency = (1.0 - relative * float(一致性增益)).clamp(0.0, 1.0)

        return (
            fused.unsqueeze(-1).repeat(1, 1, 1, 3).clamp_min(0.0),
            consistency.unsqueeze(-1).repeat(1, 1, 1, 3),
        )


NODE_CLASS_MAPPINGS = {
    "QQIlluminationBalance": QQIlluminationBalance,
    "QQDepthFusion": QQDepthFusion,
}

NODE_DISPLAY_NAME_MAPPINGS = {
    "QQIlluminationBalance": "QQ-照度均衡",
    "QQDepthFusion": "QQ-深度融合",
}
